// ── Adaptee: third-party Stripe SDK (cannot be changed) ─────────
class StripeSDK {
  createCharge({ amount, currency, description }) {
    console.log(`[Stripe] Charged ${amount} ${currency}: ${description}`);
    return { id: 'ch_123', status: 'succeeded' };
  }
}

// ── Adaptee #2: legacy PayPal module (different signature) ───────
class LegacyPayPalClient {
  sendPayment(total, curr, memo) {
    console.log(`[PayPal] Sent ${total} ${curr} (${memo})`);
    return { transactionId: 'pp_456' };
  }
}

// ── Target interface (what our system expects) ───────────────────
// In JS we document it as a class with a clear contract:
class PaymentProcessor {
  // charge(amount: number, currency: string, note: string): void
  charge(_amount, _currency, _note) {
    throw new Error('charge() must be implemented by adapter');
  }
}

// ── Adapter 1: wraps StripeSDK ───────────────────────────────────
class StripeAdapter extends PaymentProcessor {
  constructor() {
    super();
    this._stripe = new StripeSDK();
  }
  charge(amount, currency, note) {
    const result = this._stripe.createCharge({
      amount,
      currency,
      description: note,
    });
    console.log(`StripeAdapter: charge done, id=${result.id}`);
  }
}

// ── Adapter 2: wraps LegacyPayPalClient ─────────────────────────
class PayPalAdapter extends PaymentProcessor {
  constructor() {
    super();
    this._paypal = new LegacyPayPalClient();
  }
  charge(amount, currency, note) {
    const result = this._paypal.sendPayment(amount, currency, note);
    console.log(`PayPalAdapter: tx=${result.transactionId}`);
  }
}

// ── Client: knows only PaymentProcessor ─────────────────────────
class OrderService {
  constructor(processor) {
    this._processor = processor;
  }
  placeOrder(amount, currency, item) {
    console.log(`Placing order for ${item}...`);
    this._processor.charge(amount, currency, `Order: ${item}`);
    console.log('Order complete!\n');
  }
}

// ── Wire it up — swap providers without touching OrderService ────
const stripeOrder = new OrderService(new StripeAdapter());
stripeOrder.placeOrder(49.99, 'USD', 'Pro Subscription');
// Placing order for Pro Subscription...
// [Stripe] Charged 49.99 USD: Order: Pro Subscription
// StripeAdapter: charge done, id=ch_123
// Order complete!

const paypalOrder = new OrderService(new PayPalAdapter());
paypalOrder.placeOrder(29.00, 'EUR', 'Ebook Bundle');
// Placing order for Ebook Bundle...
// [PayPal] Sent 29 EUR (Order: Ebook Bundle)
// PayPalAdapter: tx=pp_456
// Order complete!

// ── Structural skeleton of the Adapter pattern ───────────────────

// 1. Target Interface — defines what the client expects
class Target {
  request() { throw new Error('Not implemented'); }
}

// 2. Adaptee — the incompatible class you want to reuse
class Adaptee {
  specificRequest() {
    return 'Adaptee: specific result';
  }
}

// 3. Adapter — bridges the two
class Adapter extends Target {
  constructor(adaptee) {
    super();
    this._adaptee = adaptee;  // composition — wraps the adaptee
  }
  request() {
    // Translate Target call → Adaptee call
    const result = this._adaptee.specificRequest();
    return `Adapter: (translated) ${result}`;
  }
}

// 4. Client — depends only on Target
function clientCode(target) {
  console.log(target.request());
}

// Usage
const adaptee = new Adaptee();
const adapter = new Adapter(adaptee);
clientCode(adapter); // Adapter: (translated) Adaptee: specific result

// ── Real-world pattern: wrapping a fetch-based HTTP client ───────
class AxiosHttpClient {
  get(url, config) { /* axios.get(url, config) */ }
}
class FetchHttpAdapter extends AxiosHttpClient {
  get(url, config) {
    // translate to native fetch signature
    return fetch(url, { headers: config?.headers });
  }
}
